 "content": "from collections import deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = [[False] * w for _ in range(h)]
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or seen[r][c]:
                continue
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and not seen[ny][nx] and grid[ny][nx] == color:
                        seen[ny][nx] = True
                        q.append((ny, nx))
            if len(cells) >= 10:
                min_r = min(y for y, x in cells)
                max_r = max(y for y, x in cells)
                min_c = min(x for y, x in cells)
                max_c = max(x for y, x in cells)
                box_area = (max_r - min_r + 1) * (max_c - min_c + 1)
                if len(cells) / box_area >= 0.55:
                    objects.append((len(cells), color))
    if not objects:
        return []
    n = len(objects)
    color = max(objects)[1]
    return [[color] * n for _ in range(n)]
